import type {WeatherInsights} from '../types';

// Pre-computed insights per property, generated by `npm run compute`, so the
// demo survives without network access. Vite's import.meta.glob keeps this
// list in sync with whatever JSON files are in this folder.
const modules = import.meta.glob<{default: WeatherInsights}>('./*.json', {eager: true});

export const FIXTURES: Record<string, WeatherInsights> = Object.fromEntries(
  Object.entries(modules).map(([path, mod]) => [path.replace(/^\.\/|\.json$/g, ''), mod.default]),
);
